<script setup lang="ts">
const route = useRoute()

// WordPress search lives at /?s=term
const searchTerm = computed(() => (route.path === '/' && typeof route.query.s === 'string') ? route.query.s : null)

// Each URL's content is a static JSON file generated by tools/import.mjs.
const path = normalizePath(route.path)
const { data: page, error } = await useAsyncData<any>(`route:${path}`, () => $fetch(`/_data/routes/${routeId(path)}.json`))

if (error.value || !page.value) {
  throw createError({ statusCode: 404, statusMessage: 'برگه پیدا نشد', fatal: true })
}

useHead(() => {
  const p = page.value
  if (!p) return {}
  return {
    title: p.seo?.title || p.title,
    meta: p.seo?.description ? [{ name: 'description', content: p.seo.description }] : [],
    bodyAttrs: { class: p.bodyClass },
    link: (p.styles?.links ?? []).map((href: string) => ({ rel: 'stylesheet', href, key: href })),
    style: (p.styles?.inline ?? []).map((css: string, i: number) => ({ innerHTML: css, key: `wp-inline-${i}` })),
  }
})
</script>

<template>
  <div id="primary">
    <div id="content">
      <SearchResults v-if="searchTerm != null" :term="searchTerm" />
      <HomePage v-else-if="page?.type === 'home'" :page="page" />
      <PostArticle v-else-if="page?.type === 'post'" :post="page" />
      <ArchiveList v-else-if="page?.type === 'archive'" :archive="page" />
      <PageArticle v-else-if="page" :page="page" />
    </div>
  </div>
</template>
